    const list = JSON.parse(fs.readFileSync(candidate, 'utf8'));
    return list.map((sc) => ({
      ...sc,
      durationMs: typeof sc.durationMs === 'number' ? sc.durationMs : 0,
    }));
  }
  return [];
}

export function runBaselineHarness(opts = {}) {
